import torch
from src.vision_core.inference.anomaly_detector import detect_anomaly


class FakeModel(torch.nn.Module):
    @staticmethod
    def forward(x):
        batch_size = x.shape[0]

        return torch.randn(
            batch_size,
            2048,
            16,
            16
        )


def test_anomaly_detection_integration():


    model = FakeModel()


    image = torch.randn(
        3,
        512,
        512
    )


    memory_banks = {
        "bottle": torch.randn(
            5000,
            2048
        )
    }


    thresholds = {
        "bottle": 1.0
    }


    prediction, anomaly_score = detect_anomaly(
        model=model,
        image=image,
        category="bottle",
        memory_banks=memory_banks,
        thresholds=thresholds,
        device="cpu"
    )

    assert anomaly_score.ndim == 0

    assert prediction in {
        "normal",
        "anomaly"
    }